WITH row_rank_1 AS (
  SELECT * FROM (
    SELECT rr.HK_LISTING_CITY, rr.HK_LISTING, rr.HK_CITY, rr.LOAD_DATETIME, rr.RECORD_SOURCE,
           ROW_NUMBER() OVER(
               PARTITION BY rr.HK_LISTING_CITY
               ORDER BY rr.LOAD_DATETIME
           ) AS row_number
    FROM "krisha_dwh"."marts_dv"."stg_dv_listings" AS rr
    WHERE rr.HK_LISTING_CITY IS NOT NULL
    AND rr.HK_LISTING IS NOT NULL
    AND rr.HK_CITY IS NOT NULL
  ) as l
  WHERE row_number = 1
),

records_to_insert AS (
    SELECT a.HK_LISTING_CITY, a.HK_LISTING, a.HK_CITY, a.LOAD_DATETIME, a.RECORD_SOURCE
    FROM row_rank_1 AS a
    LEFT JOIN "krisha_dwh"."marts_dv"."lnk_listing_city" AS d
    ON a.HK_LISTING_CITY = d.HK_LISTING_CITY
    WHERE d.HK_LISTING_CITY IS NULL
)

SELECT * FROM records_to_insert